        v.LineColor = TGuiCaptionColor.ReadAt(b, at + 0);
        v.LineStyle = (TLineStyle)b[at + 96];
        return v;
    }

    /// <summary>Encode into b[at .. at+SizeOf-1] (mirror of the GUI editor SaveComponent).</summary>
    public void WriteAt(byte[] b, int at)
    {
        (LineColor ?? new TGuiCaptionColor()).WriteAt(b, at + 0);
        b[at + 96] = (byte)LineStyle;
    }

    public byte[] ToBytes() { var b = new byte[SizeOf]; WriteAt(b, 0); return b; }

    public static TGuiLine FromBytes(byte[] b, int offset = 0) => ReadAt(b, offset);
}

